"""Fake bank documents, generated by code (ADR-0005).

Every reader gets documents laid out like its bank's own, with made-up names, numbers and amounts: the tests, the
demo data folder (demo.py) and `iplikci dev parser test` read them, and real documents never enter the repository.
files.py writes the file formats (PDF, XLS, XLSX); a module per bank lays out that bank's documents.
"""

from collections.abc import Iterable
from dataclasses import dataclass
from datetime import date
from decimal import Decimal

HOLDER = "ÖRNEK KULLANICI"


@dataclass(frozen=True)
class Move:
    """A row of an account list: money in is positive, as the banks print it."""

    day: date
    text: str
    amount: Decimal


@dataclass(frozen=True)
class CardRow:
    """A row of a card statement. A row without a day is undated, like the period's interest; a row without an
    amount is a section heading."""

    day: date | None
    text: str
    amount: Decimal | None = None
    extra: str = ""  # the installment or the foreign amount, in a column of its own


def charged(rows: Iterable[CardRow]) -> Decimal:
    """What rows add to a card's debt."""
    return sum((r.amount for r in rows if r.amount is not None), Decimal(0))


def with_balances(moves: Iterable[Move], opening: Decimal = Decimal(0)) -> list[tuple[Move, Decimal]]:
    """moves, in the order given, each with the balance after it."""
    out: list[tuple[Move, Decimal]] = []
    balance = opening
    for m in moves:
        balance += m.amount
        out.append((m, balance))
    return out
